let TSFT=null;
function tsBoxDims(shape){
 if(shape.length>=3){const [c,h,w]=shape,bw=Math.max(16,Math.min(60,(w/192)*60)),bh=Math.max(16,Math.min(60,(h/48)*60)),depth=Math.max(1,Math.min(4,Math.round(Math.log2(Math.max(1,c/8))+1)));return{w:bw,h:bh,depth}}
 const [t,f]=shape,bw=Math.max(18,Math.min(64,(t/48)*46)),bh=Math.max(10,Math.min(36,(f/256)*36));return{w:bw,h:bh,depth:0}}
function tsWrapLabel(s,max){const words=s.split(' ');const lines=[];let cur='';
 for(const w of words){if(cur&&(cur+' '+w).length>max){lines.push(cur);cur=w}else cur=cur?cur+' '+w:w}
 if(cur)lines.push(cur);return lines}
function tsFlowSVG(flow){
 const LBLW=13,LINEH=11,GAP=44,PADX=18,SHAPEY=20,skewOf=d=>d?4+d*3:0;
 let x=PADX,maxTopReq=0;
 const placed=flow.map(f=>{const d=tsBoxDims(f.shape),skew=skewOf(d.depth),lines=tsWrapLabel(f.label,LBLW),
  item={...d,skew,x,lines,shapeTxt:f.shape.join(' × ')};
  x+=Math.max(d.w+skew,LBLW*5)+GAP;maxTopReq=Math.max(maxTopReq,d.h+skew+10+lines.length*LINEH);return item});
 const totalW=x-GAP+PADX,baseY=maxTopReq+6,totalH=baseY+SHAPEY+14;
 let svg=`<svg viewBox="0 0 ${totalW} ${totalH}" width="${totalW}" height="${totalH}" style="max-width:100%;display:block" xmlns="http://www.w3.org/2000/svg"><defs><marker id="tsarrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,0L10,5L0,10z" fill="var(--mut)"/></marker></defs>`;
 placed.forEach((p,i)=>{const by=baseY-p.h,bx=p.x,cx=bx+p.w/2+p.skew/2;
  if(p.depth){const dx=p.skew,dy=p.skew;
   svg+=`<polygon points="${bx},${by} ${bx+p.w},${by} ${bx+p.w+dx},${by-dy} ${bx+dx},${by-dy}" fill="#8fb8e8" stroke="rgba(0,0,0,.18)"/>`;
   svg+=`<polygon points="${bx+p.w},${by} ${bx+p.w+dx},${by-dy} ${bx+p.w+dx},${by-dy+p.h} ${bx+p.w},${by+p.h}" fill="#2f5f99" stroke="rgba(0,0,0,.18)"/>`;
   svg+=`<rect x="${bx}" y="${by}" width="${p.w}" height="${p.h}" fill="#4a86c8" stroke="rgba(0,0,0,.18)"/>`
  }else svg+=`<rect x="${bx}" y="${by}" width="${p.w}" height="${p.h}" rx="3" fill="#6fcf97" stroke="rgba(0,0,0,.18)"/>`;
  const lblBaseY=by-p.skew-10,lblTopY=lblBaseY-(p.lines.length-1)*LINEH;
  p.lines.forEach((ln,li)=>{svg+=`<text x="${cx}" y="${lblTopY+li*LINEH}" text-anchor="middle" font-size="10" font-weight="600" style="fill:var(--ink)">${esc(ln)}</text>`});
  svg+=`<text x="${bx+p.w/2}" y="${baseY+SHAPEY}" text-anchor="middle" font-size="10" font-family="monospace" style="fill:var(--mut)">${esc(p.shapeTxt)}</text>`;
  if(i<placed.length-1){const nx=placed[i+1].x,ay=baseY-Math.max(10,p.h/2);svg+=`<line x1="${bx+p.w+p.skew+6}" y1="${ay}" x2="${nx-6}" y2="${ay}" stroke="var(--mut)" stroke-width="1.4" marker-end="url(#tsarrow)"/>`}});
 return svg+'</svg>'}
function tsFlow(){clearTimeout(TSFT);TSFT=setTimeout(async()=>{const el=$('tsflow');if(!el)return;try{const r=await api('/api/arch/describe',{method:'POST',body:JSON.stringify({arch:JSON.parse(TSET.spec)})});
 if(!r.ok){el.innerHTML=`<div class="msg bad">${r.problems.map(esc).join('<br>')}</div>`;return}
 el.innerHTML=`<div><b>${r.params.toLocaleString()}</b> parameters · <b>${r.time_steps}</b> time steps${r.hash===TSET.ps.arch_presets.crnn.hash?' · the shipped reader':''}</div><div class="tscnn">${tsFlowSVG(r.flow)}</div>`}catch(e){el.innerHTML=`<div class="msg bad">${esc(e.message)}</div>`}},250)}

const EV={a:'',b:''};
async function evLoad(){const o=$('evbody');if(!o)return;const card=$('gc')?$('gc').value:'anc';try{const [t,x]=await Promise.all([api(`/api/card/${encodeURIComponent(card)}/testset`),api(`/api/card/${encodeURIComponent(card)}/seedexp`)]);
 const looks=t.looks||[],run=x.experiments.some(e=>e.state==='running');
 const test=t.exists?`<div><span class="badge bg-green-lt">reserved</span> <b>${t.test_pages}</b> ${t.unit==='writer'?'pages of whole writers':'pages'} (${t.test_cells} labeled cells) kept out of training, tuning and every comparison · ${t.train_pages} pages (${t.train_cells} cells) left to train on · reserved ${esc(t.created)}</div>
   <div class="row" style="margin-top:6px"><button class="btn" onclick="evScore()">Score the newest run on the test set</button><span class="tag">Do this once, when you have chosen your settings. Every look is counted.</span></div>
   ${looks.length?`<div class="tag" style="margin-top:6px">Looks so far (${looks.length}): ${looks.map(l=>`${esc(l.run)} ${(l.exact*100).toFixed(0)}% [${(l.lo*100).toFixed(0)}-${(l.hi*100).toFixed(0)}]`).join(' · ')}</div>${looks.length>1?`<div class="msg warn">This test set has been looked at ${looks.length} times. Each extra look while choosing between settings makes it less trustworthy.</div>`:''}`:''}`
  :`<div class="row"><button class="btn btn-primary" onclick="evReserve()">Reserve a test set (20%)</button><span class="tag">Whole writers when writer codes exist, else whole pages. Drawn once; none of its pages are used for training, cross-validation, learning curves or comparisons from then on. It has ${t.train_pages} labeled pages now.</span></div>`;
 const rows=x.experiments.map(e=>`<tr><td><b>${esc(e.name)}</b><div class="tag">${esc(e.arch||'')}</div></td><td>${esc(e.state)}${e.state==='running'?` · seed ${e.seeds_done+1} of ${e.seeds}`:''}</td><td>${e.mean!=null?`<b>${(e.mean*100).toFixed(1)}%</b> exact in cross-validation`:'-'}${e.spread?`<div class="tag">seeds ${e.exact.map(v=>(v*100).toFixed(1)).join(', ')}% · spread ${((e.spread[1]-e.spread[0])*100).toFixed(1)} points</div>`:''}</td></tr>`).join('');
 const done=x.experiments.filter(e=>e.state==='done');
 const cmp=done.length>=2?`<div class="row" style="margin-top:8px"><label>Compare <select id="eva">${done.map(e=>`<option ${e.name===EV.a?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label><label>with <select id="evb">${done.map((e,i)=>`<option ${e.name===EV.b||(!EV.b&&i===1)?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label><button class="btn" onclick="evCompare()">Compare</button></div><div id="evcmp"></div>`:'';
 o.innerHTML=`<div class="tag"><b>Test set</b></div>${test}
  <div class="tag" style="margin-top:14px"><b>Seed experiments</b>: the settings in the panel above are trained on the same folds with several seeds (cross-validation only, no pack), so a difference can be told from chance.</div>
  ${x.message?`<div class="msg warn">${esc(x.message)}</div>`:`<div class="tag">${x.settings_tried} different setting${x.settings_tried===1?'':'s'} tried on this card.</div>`}
  <div class="row"><label>Name <input id="evname" placeholder="baseline" style="width:130px" maxlength="32"></label><label>Seeds <select id="evseeds"><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><button class="btn" ${run?'disabled':''} onclick="evRun()">Run seeds with the current settings</button><span class="tag">about the time of one cross-validation per seed</span></div><div id="evmsg" class="tag"></div>
  ${rows?`<table class="table table-vcenter"><tr><th>Experiment</th><th>State</th><th>Result</th></tr>${rows}</table>`:''}${cmp}`;
 if(run)setTimeout(evLoad,5000)}catch(e){o.innerHTML=`<span class="bad">${esc(e.message)}</span>`}}
async function evReserve(){const card=$('gc').value;if(!confirm('Reserve 20% of '+card+"'s labeled pages as a test set? It is drawn once and cannot be redrawn from here."))return;try{await api(`/api/card/${encodeURIComponent(card)}/testset/reserve`,{method:'POST',body:'{}'});evLoad()}catch(e){$('evmsg')?($('evmsg').innerHTML=`<b class="bad">${esc(e.message)}</b>`):alert(e.message)}}
async function evScore(){const card=$('gc').value,m=$('evmsg');m.textContent='Reading the test set with the newest run…';try{const r=await api(`/api/card/${encodeURIComponent(card)}/testset/score`,{method:'POST',body:'{}'});await evLoad();$('evmsg').innerHTML=`<div class="msg ${r.warning?'warn':'ok'}"><b>${(r.exact*100).toFixed(1)}%</b> exact on ${r.n} test cells (${r.pages} pages), 95% interval ${(r.lo*100).toFixed(0)}-${(r.hi*100).toFixed(0)}% · run ${esc(r.run)} · look ${r.looks}${r.warning?`<div>${esc(r.warning)}</div>`:''}</div>`}catch(e){m.innerHTML=`<b class="bad">${esc(e.message)}</b>`}}
async function evRun(){const card=$('gc').value,m=$('evmsg');try{const s=TSET.ps?tsSettings():{};await api(`/api/card/${encodeURIComponent(card)}/seedexp/run`,{method:'POST',body:JSON.stringify({name:$('evname').value.trim(),seeds:+$('evseeds').value,settings:s,pretrained:TSET.weights||'auto',max_epochs:TSET.maxep})});evLoad()}catch(e){m.innerHTML=`<b class="bad">${esc(e.message)}</b>`}}
async function evCompare(){const card=$('gc').value,a=$('eva').value,b=$('evb').value;EV.a=a;EV.b=b;const o=$('evcmp');if(a===b){o.innerHTML='<div class="msg warn">Pick two different experiments.</div>';return}try{const r=await api(`/api/card/${encodeURIComponent(card)}/seedexp/compare?a=${encodeURIComponent(a)}&b=${encodeURIComponent(b)}`),pc=v=>(v*100).toFixed(1);
 o.innerHTML=`<div class="msg ${r.verdict==='no clear difference'?'warn':'ok'}"><b>${esc(r.verdict)}</b>: ${esc(b)} minus ${esc(a)} is <b>${r.diff>=0?'+':''}${pc(r.diff)} points</b>, 95% interval ${pc(r.ci95[0])} to ${pc(r.ci95[1])} (resampling ${r.pages} pages) · on ${r.cells} cells: ${r.only_b_better} read better by ${esc(b)}, ${r.only_a_better} by ${esc(a)} (sign test p = ${r.sign_p})<div class="tag">Seed-to-seed spread: ${esc(a)} ${pc(r.a.spread[1]-r.a.spread[0])} points, ${esc(b)} ${pc(r.b.spread[1]-r.b.spread[0])} points.</div>${r.warning?`<div>${esc(r.warning)}</div>`:''}</div>`}catch(e){o.innerHTML=`<div class="msg bad">${esc(e.message)}</div>`}}
const TSET={ps:null,catalog:null,customList:null,preset:'light_lr3e-4',hp:{},aug:{},run:{},arch:'crnn',spec:null,hash:null,weights:'auto',maxep:300,check:null};
async function tsLoad(){try{if(!TSET.ps){TSET.ps=await api('/api/train/settings');TSET.hash=TSET.ps.arch_presets.crnn.hash;TSET.spec=JSON.stringify(TSET.ps.arch_presets.crnn.spec,null,1)}if(!PRET||!PRET.length)PRET=await api('/api/pretrained');if(!TSET.catalog)TSET.catalog=await api('/api/arch/catalog',{method:'POST',body:'{}'});if(!TSET.customList)TSET.customList=(await api('/api/arch/custom')).architectures;tsRender()}catch(e){$('tsbody').innerHTML=`<span class="bad">${esc(e.message)}</span>`}}
function tsDefault(k){const P=TSET.ps,pv=P.presets[TSET.preset];if(k==='lr')return pv.lr;return P.hp[k].default}
function tsAugDefault(k){const pv=TSET.ps.presets[TSET.preset].aug;return pv[k]!==undefined?pv[k]:0}
function tsVal(k){return TSET.hp[k]!==undefined?TSET.hp[k]:tsDefault(k)}
function tsAug(k){return TSET.aug[k]!==undefined?TSET.aug[k]:tsAugDefault(k)}
function tsSet(k,v,isNum,el){if(isNum){v=+v;if(isNaN(v))return}if(v===tsDefault(k))delete TSET.hp[k];else TSET.hp[k]=v;tsSum();if(el)el.closest('label').classList.toggle('changed',TSET.hp[k]!==undefined);tsBadges()}
function tsSetAug(k,v,el){v=+v;if(isNaN(v))return;if(v===tsAugDefault(k))delete TSET.aug[k];else TSET.aug[k]=v;tsSum();if(el)el.closest('label').classList.toggle('changed',TSET.aug[k]!==undefined);tsBadges()}
function tsRunVal(k){return TSET.run[k]!==undefined?TSET.run[k]:TSET.ps.run[k].default}
function tsSetRun(k,v,el){v=+v;if(isNaN(v))return;if(v===TSET.ps.run[k].default)delete TSET.run[k];else TSET.run[k]=v;tsSum();if(el)el.closest('label').classList.toggle('changed',TSET.run[k]!==undefined);tsBadges()}
function tsPreset(v){TSET.preset=v;tsRender()}
function tsResetAll(){TSET.hp={};TSET.aug={};TSET.run={};TSET.maxep=300;tsRender()}
const LEGACY_ARCHS=new Set(['crnn','crnn-small','crnn-wide','gru-crnn','cnn-ctc']);
function tsArchKind(v){if(v.startsWith('custom'))return'custom';return LEGACY_ARCHS.has(v)?'legacy':'schema-2'}
function tsBadges(){const P=TSET.ps;if(!P)return;const chgCount=(ks,o)=>ks.filter(k=>o[k]!==undefined).length,
 nGen=chgCount(['lr','optimizer','weight_decay','batch','schedule','step_every','step_gamma','grad_clip','balance','patience'],TSET.hp)+(TSET.maxep!==300?1:0),
 nEarly=chgCount(['monitor','min_delta','restore','plateau_patience'],TSET.hp)+chgCount(['checkpoint_every','keep_last'],TSET.run),
 nAug=chgCount(Object.keys(P.aug),TSET.aug);
 [['bdg-gen',nGen],['bdg-early',nEarly],['bdg-aug',nAug]].forEach(([id,c])=>{const el=$(id);if(!el)return;el.textContent=c?`${c} changed`:'';el.classList.toggle('hide',!c)})}
function tsArchSpecNow(){if(TSET.arch!=='custom'&&!TSET.arch.startsWith('custom:')){const p=TSET.ps.arch_presets[TSET.arch];if(JSON.stringify(JSON.parse(TSET.spec))===JSON.stringify(p.spec))return TSET.arch}return JSON.parse(TSET.spec)}
function tsSettings(){const hp={...TSET.hp};if(Object.keys(TSET.aug).length)hp.aug={...TSET.aug};let arch=null;try{const a=tsArchSpecNow();if(a!=='crnn')arch=a}catch(e){throw new Error('The architecture JSON is not valid JSON: '+e.message)}
 const out={};if(TSET.preset!==TSET.ps.default_preset)out.preset=TSET.preset;if(Object.keys(hp).length)out.hp=hp;if(arch!==null)out.arch=arch;if(Object.keys(TSET.run).length)out.run={...TSET.run};return out}
function tsSum(){let t='the shipped recipe';try{const s=tsSettings();const bits=[];if(s.preset)bits.push('preset '+s.preset);if(s.hp)bits.push(Object.keys(s.hp).map(k=>k==='aug'?'augmentation':k).join(', '));if(s.arch!==undefined)bits.push('network '+(typeof s.arch==='string'?s.arch:'custom'));if(bits.length)t='custom: '+bits.join(' · ');if(s.run)t+=(bits.length?' · ':'the shipped recipe · ')+'checkpoints: '+Object.entries(s.run).map(([k,v])=>k.replace('_',' ')+' '+v).join(', ')}catch(e){t='architecture JSON has an error'}$('tssum').textContent=t;if($('tssum2'))$('tssum2').textContent=t}
function tsArch(v){TSET.arch=v;TSET.check=null;if(v.startsWith('custom:')){TSET.spec=JSON.stringify({custom:v.slice(7)},null,1);TSET.hash=null}else if(v!=='custom'){const p=TSET.ps.arch_presets[v];TSET.spec=JSON.stringify(p.spec,null,1);TSET.hash=p.hash}else TSET.hash=null;tsRender()}
function tsSpec(v){TSET.spec=v;TSET.check=null;TSET.hash=null;try{const o=JSON.parse(v),m=Object.entries(TSET.ps.arch_presets).find(([k,p])=>JSON.stringify(p.spec)===JSON.stringify(o));if(m){TSET.hash=m[1].hash}}catch(e){}tsBuilder();tsWeights();tsSum()}
function compatBadges(c){const label={onnx:'ONNX',rebuild:'TFLite (rebuild)',ai_edge_torch:'ai-edge-torch',onnx2tf:'onnx2tf'};return Object.entries(label).map(([k,l])=>`<span class="badge ${c[k]&&c[k].supported?'bg-green-lt':'bg-secondary-lt'}" title="${esc((c[k]||{}).reason||'')}">${l}</span>`).join(' ')}
async function tsCheck(){const o=$('tscheck');o.innerHTML='<span class="tag">Building it, exporting ONNX and timing it…</span>';try{const a=tsArchSpecNow(),[r,c]=await Promise.all([api('/api/arch/check',{method:'POST',body:JSON.stringify({arch:a})}),api('/api/arch/compat',{method:'POST',body:JSON.stringify({arch:a})})]);TSET.check=r;if(r.hash)TSET.hash=r.hash;if(r.spec){TSET.spec=JSON.stringify(r.spec,null,1);$('tsspec').value=TSET.spec}
 o.innerHTML=r.ok?`<div class="msg ok"><b>Works.</b> ${r.params.toLocaleString()} parameters · ${r.time_steps} time steps · ${r.torch_ms} ms PyTorch, ${r.onnx_ms} ms ONNX on this machine · ONNX ${(r.onnx_bytes/1048576).toFixed(1)} MB, matches PyTorch to ${r.onnx_max_diff.toExponential(1)} · TFLite: ${r.tflite.supported?'can be built':'<b class="warn">not supported: '+esc(r.tflite.reason)+'</b>'} · ${r.shipped_weights_fit?'the shipped pretrained weights fit this network':'the shipped pretrained weights do not fit: start from scratch or pretrain it below'}</div><div style="margin-top:6px">Export: ${compatBadges(c)}</div>`:`<div class="msg bad">${r.problems.map(esc).join('<br>')}</div>`;tsWeights()}catch(e){o.innerHTML=`<div class="msg bad">${esc(e.message)}</div>`}}
async function tsBench(){const o=$('tsbench');o.innerHTML='<span class="tag">Building, exporting ONNX and timing 20 runs…</span>';try{const a=tsArchSpecNow(),r=await api('/api/export/bench',{method:'POST',body:JSON.stringify({arch:a,width:192,runs:20})});
 o.innerHTML=`<div class="msg ok"><b>${r.p50_ms} ms</b> P50, <b>${r.p95_ms} ms</b> P95${r.peak_rss_mb!=null?`, ${r.peak_rss_mb} MB peak RSS`:''}, ${(r.size_bytes/1048576).toFixed(2)} MB ONNX - CPU, onnxruntime, this machine, ${r.runs} runs at 192px wide (not a phone: use tools/benchmark_device.py for that)</div>`}catch(e){o.innerHTML=`<div class="msg bad">${esc(e.message)}</div>`}}
function tsWeights(){const sel=$('gp');if(!sel)return;const keep=sel.value||TSET.weights,mine=(PRET||[]).filter(p=>p.ok&&TSET.hash&&p.arch_hash===TSET.hash&&(p.name!=='legacy'||TSET.arch==='crnn'));
 sel.innerHTML=`<option value="auto">auto: ${TSET.arch==='crnn'?'the default weights':'weights pretrained for this network, else from scratch'}</option><option value="none">none: train from scratch</option>`+mine.map(p=>`<option value="${esc(p.name)}">${esc(p.name)}${p.default?' (default)':''}${p.images?` · ${p.images.toLocaleString()} images`:''}</option>`).join('');if([...sel.options].some(o=>o.value===keep))sel.value=keep;TSET.weights=sel.value}
const TSHELP={lr:'How fast weights change each step. Too high and training diverges; too low and it crawls.',optimizer:'The update rule: adam/adamw adapt the step per parameter, sgd is plain gradient descent.',
 weight_decay:'A penalty that shrinks weights a little each step, to reduce overfitting.',batch:'How many labeled cells are averaged into one gradient step.',
 schedule:'How the learning rate changes over training: left alone, decayed smoothly, dropped at intervals, or dropped when progress stalls.',
 step_every:'Step schedule only: how many epochs between each drop in the learning rate.',step_gamma:'Step/plateau schedules only: the multiplier applied to the learning rate at each drop.',
 grad_clip:'Caps how large a single gradient step can be, to stop rare huge updates destabilizing training. 0 turns it off.',
 balance:'Sample fields so a card type or field with many labels does not drown out one with few.',patience:'How many epochs without improvement a fold trains before stopping early.',
 maxep:'A hard ceiling on epochs per fold, win or lose, regardless of patience.',monitor:'The validation measure early stopping watches: exact match, character error rate, or loss.',
 min_delta:'How much the watched measure must improve to count as progress and reset patience.',restore:'Which checkpoint a fold keeps when it stops: the best epoch seen, or simply the last one trained.',
 plateau_patience:'Plateau schedule only: epochs without progress before the learning rate is lowered.',checkpoint_every:'How often a numbered checkpoint is saved, in epochs (0 = only ever keep the best).',
 keep_last:'How many numbered checkpoints to keep per fold; the best is always kept regardless.',preset:'A bundled starting point for the learning rate and the augmentation strengths below.',
 rot:'Random rotation applied to each cell while training, in degrees either way.',tx:'Random sideways shift applied to each cell while training, in pixels.',
 ty:'Random up/down shift applied to each cell while training, in pixels.',bright:'Random brightness change applied to each cell while training.',
 shift:'Random gray-level shift applied to each cell while training.',blur:'Chance each cell is blurred while training, simulating an out-of-focus photo.',
 noise:'Random pixel noise added to each cell while training, in gray levels.',erase:'Chance a small patch of each cell is erased while training, simulating damage or a stray mark.',
 arch:'The network that reads a cell: its layers decide capacity, speed, and which export backends it supports.'};
const tsI=k=>TSHELP[k]?`<i class="tsinfo" onclick="tsInfo(event,'${k}')">i</i>`:'';
function tsPopover(e,key,text){e.stopPropagation();e.preventDefault();let b=document.getElementById('tsip');if(!b){b=document.createElement('div');b.id='tsip';b.className='tsipbox hide';document.body.appendChild(b)}
 if(b.dataset.k===key&&!b.classList.contains('hide')){b.classList.add('hide');return}
 b.textContent=text||'';b.dataset.k=key;b.classList.remove('hide');
 const r=e.currentTarget.getBoundingClientRect();b.style.top=(r.bottom+6)+'px';b.style.left=r.left+'px';
 requestAnimationFrame(()=>{const bw=b.offsetWidth,vw=window.innerWidth;if(r.left+bw>vw-10)b.style.left=Math.max(10,vw-bw-10)+'px'})}
function tsInfo(e,k){tsPopover(e,k,TSHELP[k])}
function tsArchInfo(e){const v=TSET.arch;let text;
 if(v.startsWith('custom:')){const a=(TSET.customList||[]).find(a=>a.name===v.slice(7));text=a?`Custom architecture (htr/custom/${a.name}.py): ${(a.params/1e6).toFixed(2)}M parameters. Python code, not a spec - edit the file on disk to change it.`:'Custom architecture.'}
 else if(v==='custom'){text='A hand-edited schema-2 config (see the layers below, or the JSON textbox) that matches no saved preset.'}
 else{const p=TSET.ps.arch_presets[v];text=p?`${p.label} (${(p.params/1e6).toFixed(2)}M parameters).`:''}
 tsPopover(e,'arch-sel',text)}
document.addEventListener('click',()=>{const b=document.getElementById('tsip');if(b)b.classList.add('hide')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const b=document.getElementById('tsip');if(b)b.classList.add('hide')}});
function tsJump(id){const el=$(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})}
function tsRender(){const P=TSET.ps,pv=P.presets[TSET.preset],
 n=(k,l,step)=>`<label class="${TSET.hp[k]!==undefined?'changed':''}"><span class="tstxt">${l}${tsI(k)}</span><input type="number" class="num" step="${step||'any'}" min="${P.hp[k].min}" max="${P.hp[k].max}" value="${tsVal(k)}" onchange="tsSet('${k}',this.value,true,this)" title="${l} (${P.hp[k].min} to ${P.hp[k].max})"></label>`,
 sel=(k,l)=>`<label class="${TSET.hp[k]!==undefined?'changed':''}"><span class="tstxt">${l}${tsI(k)}</span><select onchange="tsSet('${k}',this.value==='true'?true:this.value==='false'?false:this.value,false,this)">${P.hp[k].options.map(o=>`<option value="${o}" ${String(tsVal(k))===String(o)?'selected':''}>${o===true?'yes':o===false?'no':o}</option>`).join('')}</select></label>`,
 aug=Object.entries(P.aug).map(([k,v])=>`<label class="${TSET.aug[k]!==undefined?'changed':''}"><span class="tstxt">${esc(v.label)}${tsI(k)}</span><input type="number" class="num" step="any" min="${v.min}" max="${v.max}" value="${tsAug(k)}" onchange="tsSetAug('${k}',this.value,this)" title="${esc(v.label)} (${v.min} to ${v.max})"></label>`).join(''),
 run=Object.entries(P.run).map(([k,v])=>`<label class="${TSET.run[k]!==undefined?'changed':''}"><span class="tstxt">${esc(v.label)}${tsI(k)}</span><input type="number" class="num" step="1" min="${v.min}" max="${v.max}" value="${tsRunVal(k)}" onchange="tsSetRun('${k}',this.value,this)" title="${esc(v.label)} (${v.min} to ${v.max})"></label>`).join(''),
 chgCount=(ks,o)=>ks.filter(k=>o[k]!==undefined).length,
 nGen=chgCount(['lr','optimizer','weight_decay','batch','schedule','step_every','step_gamma','grad_clip','balance','patience'],TSET.hp)+(TSET.maxep!==300?1:0),
 nEarly=chgCount(['monitor','min_delta','restore','plateau_patience'],TSET.hp)+chgCount(['checkpoint_every','keep_last'],TSET.run),
 nAug=chgCount(Object.keys(P.aug),TSET.aug),
 badge=(id,c)=>` <span id="${id}" class="badge bg-blue-lt${c?'':' hide'}">${c?c+' changed':''}</span>`;
 $('tsbody').innerHTML=`<div class="tsnav" id="tsnav"><a onclick="tsJump('ts-gen')">General</a><a onclick="tsJump('ts-early')">Early stopping</a><a onclick="tsJump('ts-aug')">Augmentation</a><a onclick="tsJump('ts-net')">Network</a><a style="margin-left:auto" onclick="tsResetAll()">Reset all to defaults</a></div>
 <div class="card" id="ts-gen"><h2>General${badge('bdg-gen',nGen)}</h2><div class="tag">Every value the trainer uses. Leave them as they are to train the shipped recipe. A filled dot marks a value you have changed from its default.</div>
 <div class="tsgrid"><label><span class="tstxt">Preset${tsI('preset')}</span><select onchange="tsPreset(this.value)">${Object.keys(P.presets).map(k=>`<option value="${k}" ${k===TSET.preset?'selected':''}>${k} (lr ${P.presets[k].lr}, rotation ${P.presets[k].aug.rot}, blur ${P.presets[k].aug.blur})</option>`).join('')}</select></label>${n('lr','Learning rate')}${sel('optimizer','Optimizer')}${n('weight_decay','Weight decay')}${n('batch','Batch size',1)}
  ${sel('schedule','Learning-rate schedule')}${n('step_every','Epochs per step (step)',1)}${n('step_gamma','Step factor (step)')}${n('grad_clip','Gradient clip (0 = off)')}${sel('balance','Balance fields')}${n('patience','Patience, epochs',1)}
  <label class="${TSET.maxep!==300?'changed':''}"><span class="tstxt">Max epochs per fold${tsI('maxep')}</span><input type="number" class="num" min="5" max="1000" value="${TSET.maxep}" onchange="TSET.maxep=+this.value;this.closest('label').classList.toggle('changed',TSET.maxep!==300);tsBadges()"></label></div></div>
 <details class="card tssec" id="ts-early"><summary><h2>Early stopping and checkpoints${badge('bdg-early',nEarly)}</h2></summary><div class="tssecbody">
  <div class="tsgrid">${sel('monitor','Early stopping watches')}${n('min_delta','Smallest improvement that counts')}${sel('restore','Weights kept when a fold stops')}${n('plateau_patience','Plateau patience, epochs (plateau schedule)',1)}
   ${run}</div>
  <div class="tag">Checkpoints let a stopped run be resumed; they are not training values and do not make the run custom.</div></div></details>
 <details class="card tssec" id="ts-aug"><summary><h2>Augmentation${badge('bdg-aug',nAug)}</h2></summary><div class="tssecbody">
  <div class="tag">How the cells are distorted while training.</div><div class="tsgrid">${aug}</div></div></details>
 <div class="card" id="ts-net"><h2>Network${TSET.arch!=='crnn'?badge('bdg-arch',1):badge('bdg-arch',0)}</h2>
 <div class="tag">Change the network to try a CNN, a wider CRNN or your own layers: the reader keeps the same cell in, scores out, so packs and the phone read it unchanged.</div>
 <div class="tsgrid" style="grid-template-columns:minmax(0,1fr)"><label class="${TSET.arch!=='crnn'?'changed':''}"><span class="tstxt">Architecture${tsI('arch')}</span><span style="display:flex;align-items:center;gap:6px;flex:1 1 auto;min-width:0"><select id="tsarch" onchange="tsArch(this.value)" style="flex:1 1 auto;min-width:0">${Object.entries(P.arch_presets).map(([k,v])=>`<option value="${k}" ${k===TSET.arch?'selected':''}>${esc(k)}: ${esc(v.label)} · ${(v.params/1e6).toFixed(2)}M</option>`).join('')}${(TSET.customList||[]).filter(a=>a.ok).map(a=>`<option value="custom:${esc(a.name)}" ${TSET.arch===`custom:${a.name}`?'selected':''}>custom: ${esc(a.name)} · ${(a.params/1e6).toFixed(2)}M</option>`).join('')}<option value="custom" ${TSET.arch==='custom'?'selected':''}>custom: edit the layers below</option></select><i class="tsinfo" title="what the selected architecture is" onclick="tsArchInfo(event)">i</i><span class="badge ${tsArchKind(TSET.arch)==='legacy'?'bg-secondary-lt':tsArchKind(TSET.arch)==='custom'?'bg-purple-lt':'bg-azure-lt'}" title="legacy: the original hash-stable 4-key spec engine · schema-2: the configurable layer-list engine · custom: a hand-written Python module">${tsArchKind(TSET.arch)}</span></span></label></div>
 <div class="row" style="margin-top:6px"><button class="btn" onclick="tsCheck()">Check architecture</button><button class="btn" onclick="tsBench()">Bench speed on this machine</button></div>
 <div id="tsbench" style="margin-top:6px"></div></div>
 <div class="card" id="ts-layers"><h2>Layers &amp; shape</h2>
 <div id="tsbuilder"></div>
 <details style="margin-top:8px"><summary class="tag" style="cursor:pointer">Edit as JSON (the same network, as text)</summary><textarea id="tsspec" rows="12" style="width:100%;max-width:760px;font-family:monospace;font-size:12px;margin-top:6px" oninput="tsSpec(this.value)" spellcheck="false">${esc(TSET.spec)}</textarea></details>
 <div id="tscheck" style="margin-top:6px">${TSET.check?'':''}</div></div>
 <div class="card" id="ts-custom"><h2>Custom architectures</h2>
 <div class="tag">htr/custom/*.py, each a build(n_classes) function, dry-run checked on load; a working one is also selectable above.</div>
 <div id="tscustom" class="tag" style="margin-top:6px">Loading…</div></div>
 <div class="card" id="ts-weights"><h2>Starting weights &amp; pretraining</h2>
 <div class="tsgrid"><label title="the weights the reader starts from before it sees your labeled cells"><span class="tstxt">Starting weights</span><select id="gp" onchange="TSET.weights=this.value" style="flex:1 1 auto;min-width:0"></select></label></div>
 <div class="row" style="margin-top:6px"><label>Pretrain this network as <input id="tspn" placeholder="name" style="width:110px" maxlength="32"></label><label>images <input id="tspi" type="number" class="num" value="30000" min="1000" max="200000"></label><label>epochs <input id="tspe" type="number" class="num" value="4" min="1" max="40"></label><button class="btn" onclick="tsPretrain()" title="draws synthetic cells and trains this network on them: about 10 minutes for the shipped size, longer for a wider one">Pretrain</button></div>
 <div id="tspmsg" class="tag" style="margin-top:6px"></div></div>`;tsBuilder();tsWeights();tsSum();tsCustomPanel()}
function tsCustomPanel(){const el=$('tscustom');if(!el)return;const list=TSET.customList||[];el.innerHTML=list.length?list.map(a=>`<span class="badge ${a.ok?'bg-green-lt':'bg-red-lt'}" title="${esc(a.ok?`htr/custom/${a.name}.py · ${a.params.toLocaleString()} parameters · select it above to use it`:(a.error||''))}">${esc(a.name)}${a.ok?` · ${(a.params/1e6).toFixed(2)}M`:' · broken'}</span>`).join(' '):'none under htr/custom/ yet'}
async function tsPretrain(){const m=$('tspmsg');try{const a=tsArchSpecNow();await api('/api/pretrain',{method:'POST',body:JSON.stringify({name:$('tspn').value.trim(),arch:a,images:+$('tspi').value,epochs:+$('tspe').value})});tsPretrainPoll()}catch(e){m.innerHTML=`<b class="bad">${esc(e.message)}</b>`}}
async function tsPretrainPoll(){const m=$('tspmsg');try{const r=await api('/api/pretrain/status');if(r.state==='running'){m.innerHTML=`<span class="warn">Pretraining ${esc(r.name)}…</span> <span class="tag">${esc((r.tail||'').trim().split('\n').pop())}</span><div class="tspbar"><i></i></div>`;setTimeout(tsPretrainPoll,4000)}else if(r.state==='done'){PRET=await api('/api/pretrained');tsWeights();m.innerHTML=`<span class="ok">Pretrained ${esc(r.name)}.</span> Choose it under Starting weights.`}else if(r.state==='failed')m.innerHTML=`<b class="bad">Pretraining failed:</b> <span class="tag">${esc((r.tail||'').slice(-300))}</span>`}catch(e){}}

const EXT={info:null};
async function extLoad(){const o=$('extbody');try{const r=await api('/api/external'),cards=$('gc')?$('gc').value:'anc';EXT.profiles=r.profiles;
 const rows=r.models.map(m=>{const b=m.benchmarks.map(x=>`<div class="tag">${esc(x.card)}: ${(x.exact*100).toFixed(0)}% exact, CER ${x.cer} on ${x.n} cells</div>`).join('')||'<div class="tag">not scored yet</div>';
  const lic=`${esc(m.licence||'licence not stated')}${m.commercial_use===true?' · commercial use ok':m.commercial_use===false?' · <b class="bad">no commercial use</b>':' · commercial use unknown'}`;
  return `<tr><td><b>${esc(m.name)}</b><div class="tag">${esc(m.profile)} · ${m.classes.toLocaleString()} characters · ${(m.bytes/1048576).toFixed(1)} MB</div>${m.ok?'':`<div class="msg bad">${esc(m.problem)}</div>`}</td><td>${lic}<div class="tag">${m.source?`<a href="${esc(m.source)}" target="_blank" rel="noopener">source</a> · `:''}${esc(m.note)}</div></td><td>${b}</td>
  <td><button class="btn" onclick="extRun('${esc(m.name)}','benchmark')">Score on ${esc(cards)}</button> <button class="btn" onclick="extRun('${esc(m.name)}','suggest')" title="writes this model's reads as label suggestions for the card; you still decide every label">Suggest labels</button> <button class="btn" onclick="extRemove('${esc(m.name)}')">Remove</button></td></tr>`}).join('');
 o.innerHTML=`<div class="tag">An outside model is used as it is. It cannot start a training run: that needs weights in our own network's shape (Starting weights above).</div>
  ${rows?`<table class="table table-vcenter"><tr><th>Model</th><th>Licence</th><th>Results</th><th></th></tr>${rows}</table>`:'<div class="tag" style="margin:8px 0">None imported yet.</div>'}<div id="extmsg" class="tag"></div>
  <h2 style="font-size:14px;margin-top:14px">Import from Hugging Face</h2>
  <div class="row"><label>Repository <input id="hfrepo" placeholder="PaddlePaddle/PP-OCRv6_small_rec_onnx" style="width:320px"></label><button class="btn" onclick="extLookup()">Look up</button></div><div id="hfinfo"></div>`}catch(e){o.innerHTML=`<span class="bad">${esc(e.message)}</span>`}}
async function extLookup(){const o=$('hfinfo');o.innerHTML='<div class="tag">Looking up…</div>';try{const i=await api('/api/external/hf?repo='+encodeURIComponent($('hfrepo').value.trim()));EXT.info=i;
 const opt=(re)=>i.files.filter(f=>re.test(f.name)).map(f=>`<option value="${esc(f.name)}">${esc(f.name)} (${(f.bytes/1048576).toFixed(1)} MB)</option>`).join('');
 o.innerHTML=`<div class="msg ${i.gated?'warn':''}"><b>${esc(i.repo)}</b> · licence: <b>${esc(i.licence||'not stated')}</b>${i.gated?' · gated: needs access on your Hugging Face account':''} <a href="${esc(i.url)}" target="_blank" rel="noopener">read the model card</a></div>
  <div class="row"><label>Model file <select id="hfonnx">${opt(/\.onnx$/i)}</select></label><label>Characters file <select id="hfchars">${opt(/\.(ya?ml|json|txt)$/i)}</select></label><label>Type <select id="hfprof">${Object.entries(EXT.profiles).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></label></div>
  <div class="row"><label>Name <input id="hfname" value="${esc(i.repo.split('/')[1].toLowerCase().replace(/[^a-z0-9_-]/g,'_').slice(0,40))}"></label><label>Commercial use <select id="hfcom"><option value="">unknown</option><option value="yes">allowed</option><option value="no">not allowed</option></select></label><label>Digits <select id="hfdig"><option value="">as the model writes them</option><option value="1">map Bengali digits to 0-9</option></select></label></div>
  <div class="row"><label><input type="checkbox" id="hfok"> I have read the licence above and it allows this use here</label><button class="btn btn-primary" onclick="extImport()">Download and import</button></div>`}catch(e){o.innerHTML=`<div class="msg bad">${esc(e.message)}</div>`}}
async function extImport(){const m=$('extmsg');if(!$('hfok').checked){m.innerHTML='<b class="bad">Tick the licence box first.</b>';return}
 m.textContent='Downloading and checking the model…';try{await api('/api/external/import',{method:'POST',body:JSON.stringify({repo:EXT.info.repo,name:$('hfname').value.trim(),onnx_file:$('hfonnx').value,charset_file:$('hfchars').value,profile:$('hfprof').value,commercial:$('hfcom').value,digit_map:!!$('hfdig').value,accept_licence:true})});await extLoad();$('extmsg').innerHTML='<span class="ok">imported</span>'}catch(e){m.innerHTML=`<b class="bad">${esc(e.message)}</b>`}}
async function extRun(name,what){const m=$('extmsg'),card=$('gc')?$('gc').value:'anc';m.textContent=(what==='benchmark'?'Scoring ':'Reading ')+card+' with '+name+'…';try{const r=await api(`/api/external/${encodeURIComponent(name)}/${what}?card=${encodeURIComponent(card)}`,{method:'POST',body:'{}'});await extLoad();$('extmsg').innerHTML=what==='benchmark'?`<span class="ok">${r.cells} cells scored</span> · ${(r.overall.exact*100).toFixed(0)}% exact${r.skipped.two_line_cells?` · ${r.skipped.two_line_cells} two-line cells not read`:''}`:`<span class="ok">${r.cells} suggestions written</span> for ${esc(card)}: open Label to see them`}catch(e){m.innerHTML=`<b class="bad">${esc(e.message)}</b>`}}
async function extRemove(name){if(!confirm('Remove '+name+' and its scores from Studio?'))return;try{await api(`/api/external/${encodeURIComponent(name)}/remove`,{method:'POST',body:'{}'});extLoad()}catch(e){$('extmsg').innerHTML=`<b class="bad">${esc(e.message)}</b>`}}

async function gatePoll(){clearTimeout(GTIMER);try{const [t,cs,pr]=await Promise.all([api('/api/train/status'),api('/api/cards'),api('/api/pretrained')]);PRET=pr;const run=t.state==='running'||t.state==='stalled';GRUN=t.run||null;
 if(!GCARD)GCARD=t.card||'anc';const gc=cs.find(c=>c.id===GCARD)||cs[0];
 let h=`<div class="row"><label>Card <select id="gc" onchange="GCARD=this.value;BF.card=null;gatePoll()">${cs.map(c=>`<option value="${esc(c.id)}" ${c.id===gc.id?'selected':''}>${esc(c.id)}${c.trainable?'':' (not ready)'}</option>`).join('')}</select></label><label>Target: lower 95% bound at least <input id="gt" type="number" min="50" max="100" value="${t.target??85}" class="num">%</label><label>Min held-out cells <input id="gn" type="number" min="1" value="${t.min_n??20}" class="num"></label><button class="btn btn-primary" id="gs" ${t.state==='running'||!gc.trainable?'disabled':''} onclick="gateStart()">Train + gate + export</button>${t.state==='running'?`<button class="btn" id="gstop" ${GSTOPPING===t.run?'disabled':''} onclick="gateStop()" title="finishes the current epoch and keeps the checkpoints">${GSTOPPING===t.run?'Stopping after this epoch…':'Stop'}</button>`:''}${t.resumable&&t.state!=='running'?`<button class="btn" id="gresume" onclick="gateResume('${esc(t.run)}')" title="continue ${esc(t.run)} from its checkpoints">Resume ${esc(t.run)}</button>`:''}<a class="tag" href="http://127.0.0.1:8766" target="_blank">Label more cells (opens the labeler)</a></div>${splitRow(t.state==='running')}
 <div class="tag">A field ships only if the lower end of its 95% interval, measured on pages the model never saw (pooled 5-fold CV), meets the target with enough cells. Otherwise it is needs-review. The shipped reader is trained on all pages; its held-out numbers come from the same recipe in CV.</div>
 <div class="tag"><b>${esc(gc.id)}</b>: ${gc.labels.cells} labeled cells on ${gc.labels.pages} pages${gc.grid?` · ${gc.grid.fields} fields x ${gc.grid.visits} visits`:''}${gc.pack_versions.length?` · latest pack v${gc.pack_versions[gc.pack_versions.length-1]}`:' · no pack yet'}${gc.trainable?'':` · <b class="warn">not ready: ${esc(gc.blocker)}</b>`}</div>`;
 if(t.state!=='none'){const steps=['labels','cv','final','export','done'],i=Math.max(0,steps.indexOf(t.stage));
  h+=`<div class="row" style="margin-top:8px"><b class="${t.state==='done'?'ok':t.state==='error'?'bad':'warn'}">${t.state.toUpperCase()}</b><span class="tag">${esc(t.card||'anc')} · ${t.stage==='stopped'?'stopped by you; checkpoints kept'+(t.resumable?', press Resume to continue':''):'stage '+(steps.indexOf(t.stage)<0?t.stage:(i+1)+'/5 '+t.stage)} · ${esc(t.detail||'')} · ${t.elapsed??0}s${t.fold_epochs&&Object.keys(t.fold_epochs).length?' · epochs per fold: '+Object.entries(t.fold_epochs).map(([k,v])=>k+':'+v).join(' '):''}</span></div>
  ${t.stage==='stopped'?'':`<div style="height:10px;background:var(--line);border-radius:6px;overflow:hidden"><div style="height:100%;width:${t.state==='done'?100:i*20+(t.stage==='cv'?(t.cv_done||0)*3:0)}%;background:var(--acc)"></div></div>`}`}
 if(t.results){const r=t.results,ok=!r.pack.validation_errors.length;
  h+=`<div class="msg ${ok?'':'bad'}" style="margin-top:10px"><b>${ok?'Pack written and validated':'Pack failed validation'}:</b> ${esc(r.pack.id)} v${r.pack.version} · shipped fields: ${r.pack.shipped.length} of ${r.fields.length+r.unlabeled_fields.length} · <span class="tag">${esc(r.pack.path)}</span>
  <div class="tag">${r.pretrained?`started from ${esc(r.pretrained.name)} weights${r.pretrained.images?` (${r.pretrained.images.toLocaleString()} images, ${r.pretrained.epochs} epochs)`:''} · `:''}${r.n_cells} labeled cells on ${r.n_pages} pages · pooled held-out exact ${(r.cv_all.exact*100).toFixed(0)}% [${(r.cv_all.lo*100).toFixed(0)}-${(r.cv_all.hi*100).toFixed(0)}] · final reader ${r.final_epochs} epochs · ONNX parity: max diff ${r.parity.max_abs_diff.toExponential(1)}, decoded text identical on ${r.parity.cells} cells · ${r.tflite?(r.tflite.built?`TFLite reader ${(r.tflite.bytes/1048576).toFixed(1)} MB, max diff from ONNX ${r.tflite.parity.max_abs_diff.toExponential(1)} on ${r.tflite.parity.cells} cells`:`<b class="warn">no TFLite reader: ${esc(r.tflite.reason)}</b>`):'no TFLite reader (run predates it)'} · ${r.minutes} min</div></div>
  <table class="table table-vcenter"><tr><th>Field</th><th>Held-out</th><th>Exact</th><th>95% interval</th><th>CER</th><th>Decision</th></tr>${r.fields.map(gateRow).join('')}</table>
  ${r.unlabeled_fields.length?`<div class="tag">No labeled cells, so needs-review: ${r.unlabeled_fields.map(esc).join(', ')}</div>`:''}`}
 $('gbody').innerHTML=h;splitLoad(gc.id,+($('gn').value||20));dsLoad(gc.id);bfLoad(gc.id,run);cvLoad(t.run,run);GTIMER=setTimeout(gatePoll,run?4000:30000)}catch(e){GTIMER=setTimeout(gatePoll,10000)}}
async function gateStop(){if(!confirm('Stop the run? It finishes the current epoch and keeps its checkpoints, so you can resume it later.'))return;try{const r=await api('/api/train/stop',{method:'POST',body:'{}'});GSTOPPING=r.run;gatePoll()}catch(e){alert(e.message)}}
async function gateResume(run){try{await api('/api/train/resume',{method:'POST',body:JSON.stringify({run})});GSTOPPING=null;CV.sel=null;gatePoll()}catch(e){alert(e.message)}}
let GRUN=null,GSTOPPING=null;
const BF={card:null,t:0};
async function bfLoad(card,running,force){if(!force&&BF.card===card&&(running||Date.now()-BF.t<20000))return;BF.card=card;BF.t=Date.now();const o=$('bfbody');if(!o)return;try{const r=await api(`/api/card/${encodeURIComponent(card)}/checklist`);if(BF.card!==card)return;const lv={ok:'ready',info:'note',warn:'check',bad:'fix'};
 o.className='';o.innerHTML=`<div class="${r.ready?'ok':'bad'}" style="font-weight:600;margin-bottom:4px">${r.ready?'Nothing blocks training '+esc(card):'Training '+esc(card)+' is blocked until the red items are fixed'}</div><ul class="bfl">${r.checks.map(c=>`<li class="L-${esc(c.level)}"><span class="dot"></span><span class="lv ${esc(c.level)}">${lv[c.level]||esc(c.level)}</span><div>${esc(c.message)}${c.hint?`<span class="hint">${esc(c.hint)}</span>`:''}</div></li>`).join('')}</ul>`}catch(e){o.innerHTML=`<span class="bad">${esc(e.message)}</span>`}}
const CV={sel:null,key:''},CVCOL=['var(--s1)','var(--s2)','var(--s3)','#8a63d2','#c9a227','#d6409f','#5b6b7a'];
function svgLines(o){const W=560,H=230,L=44,R=12,T=14,B=34,xs=o.series.flatMap(s=>s.pts.map(p=>p[0])),ys=o.series.flatMap(s=>s.pts.map(p=>p[1]));if(!xs.length)return '';
 const x0=Math.min(...xs),x1=Math.max(...xs,x0+1);let y0=o.ymin!==undefined?o.ymin:Math.min(...ys),y1=o.ymax!==undefined?o.ymax:Math.max(...ys);if(y1<=y0)y1=y0+1;
 const X=v=>L+(v-x0)/(x1-x0)*(W-L-R),Y=v=>T+(1-(v-y0)/(y1-y0))*(H-T-B);let g='';
 for(let i=0;i<=4;i++){const v=y0+(y1-y0)*i/4;g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${L-6}" y="${Y(v)+3}" text-anchor="end">${esc(o.fmt(v))}</text>`}
 for(let i=0;i<=4;i++){const v=Math.round(x0+(x1-x0)*i/4);g+=`<text x="${X(v)}" y="${H-16}" text-anchor="middle">${v}</text>`}
 g+=`<text x="${(L+W-R)/2}" y="${H-3}" text-anchor="middle">epoch</text>`;
 for(const s of o.series){g+=`<polyline fill="none" stroke="${s.color}" stroke-width="1.8" stroke-linejoin="round" ${s.dash?'stroke-dasharray="4 3"':''} points="${s.pts.map(p=>X(p[0]).toFixed(1)+','+Y(p[1]).toFixed(1)).join(' ')}"/>`;
  if(s.best)g+=`<circle cx="${X(s.best[0])}" cy="${Y(s.best[1])}" r="4.5" fill="var(--card)" stroke="${s.color}" stroke-width="2"><title>${esc(s.name)} best: epoch ${s.best[0]}, ${esc(o.fmt(s.best[1]))}</title></circle>`}
 return `<div><div class="tag" style="margin-bottom:4px"><b>${esc(o.title)}</b></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(o.title)}">${g}</svg></div>`}
function cvDraw(c){const ks=Object.keys(c.folds).sort((a,b)=>a-b);if(!ks.length&&!(c.final||[]).length)return '<span class="tag">No curves yet: the trainer writes them after every epoch of every fold.</span>';
 const col=k=>CVCOL[k%CVCOL.length],ex=ks.map(k=>({name:'fold '+k,color:col(k),pts:c.folds[k].map(e=>[e.epoch,e.val_exact*100]),best:(()=>{const b=c.folds[k].filter(e=>e.best).pop();return b?[b.epoch,b.val_exact*100]:null})()})),
 ls=ks.map(k=>({name:'fold '+k,color:col(k),pts:c.folds[k].map(e=>[e.epoch,e.loss])})),lg=ks.map(k=>`<span><i style="background:${col(k)}"></i>fold ${k}</span>`).join('')+(ks.length?'<span>&#9675; best epoch</span>':'');
 let h=`<div class="cvlg">${lg}</div><div class="cvg">${ks.length?svgLines({title:'Validation exact match, % of cells',series:ex,ymin:0,ymax:100,fmt:v=>v.toFixed(0)+'%'})+svgLines({title:'Training loss',series:ls,ymin:0,fmt:v=>v.toFixed(2)}):''}${(c.final||[]).length?svgLines({title:'Final reader: training loss',series:[{name:'final',color:'var(--s3)',pts:c.final.map(e=>[e.epoch,e.loss])}],ymin:0,fmt:v=>v.toFixed(2)}):''}</div>`;
 const ep=ks.map(k=>{const f=c.folds[k],b=f.filter(e=>e.best).pop();return `fold ${k}: ${f.length} epochs${b?`, best at ${b.epoch} (${(b.val_exact*100).toFixed(1)}%)`:''}`}).join(' · ');return h+`<div class="tag" style="margin-top:6px">${esc(ep)}</div>`}
async function cvLoad(latest,running){const head=$('cvhead'),body=$('cvbody');if(!head||!body)return;const run=CV.sel||latest;if(!run){body.textContent='no run yet';return}
 try{const [runs,c]=await Promise.all([api('/api/runs'),api(`/api/run/${encodeURIComponent(run)}/curves`)]);const key=run+'|'+runs.map(r=>r.name).join(',');
  if(key!==CV.key){CV.key=key;head.innerHTML=`<div class="row"><label>Run <select onchange="CV.sel=this.value===GRUN?null:this.value;cvLoad(GRUN,false)">${runs.map(r=>`<option value="${esc(r.name)}" ${r.name===run?'selected':''}>${esc(r.name)}${r.name===latest?' (latest)':''} · ${esc(r.state)}</option>`).join('')}</select></label></div>`}
  body.className='';body.innerHTML=cvDraw(c)}catch(e){body.innerHTML=`<span class="bad">${esc(e.message)}</span>`}}
async function gateStart(){try{const s=TSET.ps?tsSettings():{};await api('/api/train/start',{method:'POST',body:JSON.stringify({card:$('gc').value,target:+$('gt').value,min_n:+$('gn').value,pretrained:$('gp')?$('gp').value:'auto',max_epochs:TSET.maxep,settings:s,split:splitBody()})});gatePoll()}catch(e){alert(e.message)}}

